import React, { useEffect, useState, useRef } from 'react';
import { initFirebase, subscribeToShapes, subscribeToCursors, addShapeToRemote, clearCanvasRemote, updateShapeInRemote } from './services/firebase';
import { Shape, Tool, UserCursor, ShapeType } from './types';
import { USER_COLORS, DEFAULT_FILL, DEFAULT_STROKE } from './constants';
import Canvas from './components/Canvas';
import Toolbar from './components/Toolbar';
import AiSidebar from './components/AiSidebar';
import PropertiesPanel from './components/PropertiesPanel';
import { doc, deleteDoc } from 'firebase/firestore';

const USER_ID = Math.random().toString(36).substr(2, 9);
const USER_COLOR = USER_COLORS[Math.floor(Math.random() * USER_COLORS.length)];
const NAMES = ['Alex', 'Sam', 'Jordan', 'Taylor', 'Casey', 'Riley'];
const USER_NAME = NAMES[Math.floor(Math.random() * NAMES.length)];

const App: React.FC = () => {
  const [shapes, setShapes] = useState<Shape[]>([]);
  const [cursors, setCursors] = useState<UserCursor[]>([]);
  const [activeTool, setActiveTool] = useState<Tool>(Tool.SELECT);
  const [isAiOpen, setIsAiOpen] = useState(false);
  const [firebaseError, setFirebaseError] = useState(false);
  const [selectedShapeId, setSelectedShapeId] = useState<string | null>(null);

  const svgRef = useRef<SVGSVGElement>(null);
  const dbRef = useRef<any>(null);

  useEffect(() => {
    const db = initFirebase();
    dbRef.current = db;
    if (!db) {
        setFirebaseError(true);
        setShapes([]); 
        return;
    }

    const unsubscribeShapes = subscribeToShapes((newShapes) => {
        setShapes(newShapes);
    });

    const unsubscribeCursors = subscribeToCursors(USER_ID, (newCursors) => {
        setCursors(newCursors);
    });

    return () => {
        unsubscribeShapes();
        unsubscribeCursors();
    };
  }, []);

  const handleToolChange = (tool: Tool) => {
    setActiveTool(tool);
    if (tool !== Tool.SELECT) {
        setSelectedShapeId(null);
    }
    if (tool === Tool.AI_MAGIC) {
        setIsAiOpen(true);
    }
  };

  const handleAiClose = () => {
      setIsAiOpen(false);
      setActiveTool(Tool.SELECT);
  };

  const handleAddGeneratedShapes = (generatedShapes: Partial<Shape>[]) => {
      generatedShapes.forEach(partial => {
          const newShape: Omit<Shape, 'id'> = {
            type: (partial.type as ShapeType) || ShapeType.RECTANGLE,
            x: partial.x || 100,
            y: partial.y || 100,
            width: partial.width || 50,
            height: partial.height || 50,
            radius: partial.radius || 25,
            text: partial.text || '',
            fill: partial.fill || DEFAULT_FILL,
            stroke: partial.stroke || DEFAULT_STROKE,
            strokeWidth: 2,
            createdAt: Date.now(),
          };
          if (newShape.type === ShapeType.CIRCLE && !newShape.radius) newShape.radius = 30;

          if (firebaseError) {
             const shapeWithId = { ...newShape, id: Math.random().toString() } as Shape;
             setShapes(prev => [...prev, shapeWithId]);
          } else {
             addShapeToRemote(newShape);
          }
      });
  };

  const handleUpdateShape = (updates: Partial<Shape>) => {
      if (selectedShapeId) {
          updateShapeInRemote(selectedShapeId, updates);
      }
  };

  const handleDeleteShape = async () => {
      if (selectedShapeId && dbRef.current) {
           try {
               await deleteDoc(doc(dbRef.current, 'shapes', selectedShapeId));
               setSelectedShapeId(null);
           } catch (err) {
               console.error(err);
           }
      }
  };

  const handleBringToFront = () => {
      if (selectedShapeId) {
          updateShapeInRemote(selectedShapeId, { createdAt: Date.now() });
      }
  };

  const handleSendToBack = () => {
      if (selectedShapeId && shapes.length > 0) {
          const minTime = Math.min(...shapes.map(s => s.createdAt));
          updateShapeInRemote(selectedShapeId, { createdAt: minTime - 1000 });
      }
  };

  const handleExport = () => {
      if (!svgRef.current) return;
      const svgData = new XMLSerializer().serializeToString(svgRef.current);
      const blob = new Blob([svgData], { type: "image/svg+xml;charset=utf-8" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `canvas-${Date.now()}.svg`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  const selectedShape = shapes.find(s => s.id === selectedShapeId);

  return (
    <div className="w-full h-full flex flex-col overflow-hidden bg-gray-100">
      <div className="absolute top-4 right-4 z-10 flex gap-2 items-center">
         {firebaseError && (
             <div className="bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full text-xs border border-yellow-200 font-medium">
                 ⚠️ Offline Mode (Config Missing)
             </div>
         )}
         <div className="bg-white px-3 py-1 rounded-full shadow-sm border border-gray-200 text-xs font-medium text-gray-600 flex items-center gap-2">
             <span className="w-2 h-2 rounded-full" style={{ backgroundColor: USER_COLOR }}></span>
             {USER_NAME} (You)
         </div>
      </div>

      <Toolbar 
        activeTool={activeTool} 
        setTool={handleToolChange} 
        onClear={() => !firebaseError && clearCanvasRemote()}
        onExport={handleExport}
      />

      {selectedShape && (
          <PropertiesPanel 
            selectedShape={selectedShape}
            onUpdate={handleUpdateShape}
            onDelete={handleDeleteShape}
            onBringToFront={handleBringToFront}
            onSendToBack={handleSendToBack}
          />
      )}

      <div className="flex-1 relative">
        <Canvas 
            ref={svgRef}
            shapes={shapes}
            activeTool={activeTool}
            setTool={handleToolChange}
            cursors={cursors}
            userId={USER_ID}
            userName={USER_NAME}
            userColor={USER_COLOR}
            selectedShapeId={selectedShapeId}
            onSelectShape={setSelectedShapeId}
        />

        <AiSidebar 
            isOpen={isAiOpen} 
            onClose={handleAiClose}
            onAddShapes={handleAddGeneratedShapes}
            currentShapes={shapes}
        />
      </div>
    </div>
  );
};

export default App;

